'use strict';

// MAIN //

/**
* Returns defaults.
*
* @private
* @returns {Object} default options
*
* @example
* var o = defaults();
* // returns {...}
*/
function defaults() {
	return {
		// Grid alignment to apply to rows and columns:
		'align': 'none',

		// Bounds calculation method to use for determining the extent of a sub-plot:
		'bounds': 'full',

		// Boolean flag indicating whether to center child elements within their respective rows and columns:
		'center': false,

		// Alignment of footers relative to their bands (`null` indicates positioning using the coordinate of the nearest grid content cell):
		'footerBand': null,

		// Alignment of headers relative to their bands (`null` indicates positioning using the coordinate of the nearest grid content cell):
		'headerBand': null,

		// Offset (in pixels) by which to displace header, footer, and title cells from the edges of the grid:
		'offset': 0,

		// Anchor position for placing titles relative to their bands:
		'titleAnchor': 'start',

		// Alignment of titles relative to their bands:
		'titleBand': 0.5
	};
}


// EXPORTS //

module.exports = defaults;
